use corpse_core::{startup,generation};use serde_json::json;
fn main(){for i in 0..32{let seed=if i==0{"r37-event-count-0047".into()}else if i==1{"heart-audit-000071".into()}else if i==2{"生成-é-🌱-37".into()}else{format!("r38-accessible-{i}")};let result=(||{let mut r=startup::new_run_shell_revision(&seed,"Unblessed",false,38.)?;startup::ensure_floors(&mut r,40)?;let mut errors=vec![];for f in &r.floors{let reachable=generation::reachable_without_braziers(f,None);if !generation::validate_floor_generation(f){errors.push(format!("generation-invalid:{}",f.depth));}for item in &*r.ground[&(f.depth as u32).to_string()]{let at=item.y as usize*f.width()+item.x as usize;if !reachable.contains(&at){errors.push(format!("unreachable-item:{}:{}:{},{}",f.depth,item.item.name,item.x,item.y));}}}Ok::<_,String>(errors)})();println!("{}",json!({"seed":seed,"result":result}));}}
